	/// <summary>
	/// Magnification matrix
	/// </summary>
	[StructLayout(LayoutKind.Sequential)]
	public struct Transformation
	{
		public float m00;
		public float m01;
		public float m02;
		public float m10;
		public float m11;
		public float m12;
		public float m20;
		public float m21;
		public float m22;

		public Transformation(float magnificationFactor)
			: this()
		{
			m00 = magnificationFactor;
			m11 = magnificationFactor;
			m22 = 1.0f;
		}
	}

	/// <summary>
	/// Transformation matrix
	/// </summary>
	[StructLayout(LayoutKind.Sequential)]
	public struct ColorEffect
	{
		// 25 floats, row-major (R-row, G-row, B-row, A-row, W-row)
		[MarshalAs(UnmanagedType.ByValArray, SizeConst = 25)]
		public float[] transform;

		public ColorEffect(float[,] matrix)
		{
			if (matrix == null)
				throw new ArgumentNullException(nameof(matrix));
				
			if (matrix.GetLength(0) != 5 || matrix.GetLength(1) != 5)
				throw new ArgumentException("Must be a 5×5 matrix", nameof(matrix));

			transform = new float[25];
			for (int r = 0; r < 5; r++)
				for (int c = 0; c < 5; c++)
					transform[r * 5 + c] = matrix[r, c];
		}

		public override string ToString()
		{
			return "ColorEffect[" + string.Join(",", transform) + "]";
		}
	}

	/// <summary>
	/// A Wrapper for a RECT struct
	/// </summary>
	[StructLayout(LayoutKind.Sequential)]
	public struct RECT
	{
		/// <summary>
		/// Position of left edge
		/// </summary>
		public int left;

		/// <summary>
		/// Position of top edge
		/// </summary>
		public int top;

		/// <summary>
		/// Position of right edge
		/// </summary>
		public int right;

		/// <summary>
		/// Position of bottom edge
		/// </summary>
		public int bottom;

		public RECT(int left, int top, int right, int bottom)
		{
			this.left = left;
			this.right = right;
			this.top = top;
			this.bottom = bottom;
		}

		public RECT(int width, int height)
		{
			this.left = 0;
			this.top = 0;
			this.right = width;
			this.bottom = height;
		}

		public override bool Equals(object obj)
		{
			if (obj is RECT r)
			{
				return (r.left == left && r.right == right && r.top == top && r.bottom == bottom);
			}
			return false;
		}

		public override int GetHashCode()
		{
			// Attempting a minor degree of "hash-ness" here
			return ((left ^ top) ^ right) ^ bottom;
		}

		public static bool operator ==(RECT a, RECT b)
		{
			return (a.left == b.left && a.right == b.right && a.top == b.top && a.bottom == b.bottom);
		}

		public static bool operator !=(RECT a, RECT b)
		{
			return !(a == b);
		}
	}

